insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r18-v1','0.1.0','The new manager: read between the lines','reading','guided_practice','Read the passage. Choose the correct letter, A, B, C or D, for each question.','The answer is not written directly. Find the related sentences and ask what must be true if they are true, without adding outside ideas.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "What can we infer about Mrs Tan’s approach?", "accepted_answers": ["A"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  She wanted to understand the problems before acting"}, {"value": "B", "label": "B  She disliked the cooks"}, {"value": "C", "label": "C  She had worked in the kitchen before"}, {"value": "D", "label": "D  She planned to close the restaurant"}]}, {"id": "q2", "prompt": "What does the waiters’ observation suggest?", "accepted_answers": ["B"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  She was often late"}, {"value": "B", "label": "B  She worked long hours"}, {"value": "C", "label": "C  She ate too much"}, {"value": "D", "label": "D  She did not trust the waiters"}]}, {"id": "q3", "prompt": "Why did she probably remove four dishes?", "accepted_answers": ["C"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  The chef asked her to"}, {"value": "B", "label": "B  They were too cheap"}, {"value": "C", "label": "C  Customers often sent them back"}, {"value": "D", "label": "D  The owner disliked them"}]}, {"id": "q4", "prompt": "What can we infer about the restaurant before Mrs Tan arrived?", "accepted_answers": ["D"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  It served only breakfast"}, {"value": "B", "label": "B  It was closed at weekends"}, {"value": "C", "label": "C  It had too many staff"}, {"value": "D", "label": "D  It was usually not full at lunchtime"}]}, {"id": "q5", "prompt": "Why did one of the chefs probably leave?", "accepted_answers": ["A"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  He was unhappy with the changes"}, {"value": "B", "label": "B  He was asked to manage breakfast"}, {"value": "C", "label": "C  He wanted to work at lunchtime"}, {"value": "D", "label": "D  The restaurant closed"}]}, {"id": "q6", "prompt": "What does the owner’s request at the end suggest?", "accepted_answers": ["B"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  The breakfast room was closing"}, {"value": "B", "label": "B  He was pleased with her work"}, {"value": "C", "label": "C  He wanted her to leave the restaurant"}, {"value": "D", "label": "D  He disagreed with her prices"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 12, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "When Mrs Tan took over the hotel restaurant, she did not change the menu at once. Instead, for the first month she ate lunch in the kitchen with the cooks and asked them which dishes customers sent back most often. The waiters noticed that she always arrived before them and left after them. In her second month, she removed four dishes and introduced two cheaper set lunches. Some of the older staff were unhappy, and one of the chefs left. By the end of the year, however, the restaurant was full at lunchtime for the first time in years, and the hotel owner asked her to manage the breakfast room as well.", "teacher_notes": "1 A — a month of asking before changing.\n2 B — always arrived before and left after them.\n3 C — she had asked which dishes were sent back.\n4 D — “full at lunchtime for the first time in years”.\n5 A — follows “Some of the older staff were unhappy”.\n6 B — more responsibility implies approval.\nTeach: every inference must point to a sentence; reject options that need outside knowledge.", "focus": "Infer unstated meaning: reach conclusions the text supports but does not state."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'00d973dd6cd0ffd774e8a350a759a4061b673fddb31b8ab96c21ed520c8d4427',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r19-v1','0.1.0','The bread run: read between the lines','reading','independent_check','Read the passage. Choose the correct letter, A, B, C or D, for each question. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','The answer is not written directly. Find the related sentences and ask what must be true if they are true, without adding outside ideas.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "How did Daniyar probably learn about the problem?", "accepted_answers": ["C"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  From a newspaper"}, {"value": "B", "label": "B  From the bakeries"}, {"value": "C", "label": "C  From his mother"}, {"value": "D", "label": "D  From the shelter manager"}]}, {"id": "q2", "prompt": "What can we infer from “it meant giving up his gym membership”?", "accepted_answers": ["A"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  He could not easily afford both the van and the gym"}, {"value": "B", "label": "B  He disliked exercise"}, {"value": "C", "label": "C  The van was free"}, {"value": "D", "label": "D  The gym had closed"}]}, {"id": "q3", "prompt": "Why did he probably buy the van?", "accepted_answers": ["B"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  To visit his mother"}, {"value": "B", "label": "B  To carry more bread"}, {"value": "C", "label": "C  To drive to the gym"}, {"value": "D", "label": "D  To sell it later"}]}, {"id": "q4", "prompt": "What does the manager’s comment suggest about Friday breakfasts before Daniyar began?", "accepted_answers": ["D"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  They were cooked by the bakers"}, {"value": "B", "label": "B  They were never served"}, {"value": "C", "label": "C  They were free only for volunteers"}, {"value": "D", "label": "D  They sometimes ran out"}]}, {"id": "q5", "prompt": "What does his condition for the interview suggest?", "accepted_answers": ["A"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  He did not want attention for himself"}, {"value": "B", "label": "B  He wanted to become famous"}, {"value": "C", "label": "C  He disliked the bakeries"}, {"value": "D", "label": "D  He wanted to be paid"}]}, {"id": "q6", "prompt": "What can we infer about the bread he collects?", "accepted_answers": ["C"], "taxonomy_node_id": "ef91c64b-df96-4ea3-9ac2-a9f89526b23b", "supporting_node_id": "c591b5d5-06ee-4107-be00-1947ce662d09", "options": [{"value": "A", "label": "A  The bakeries deliver it themselves"}, {"value": "B", "label": "B  The bakeries ask to be paid for it"}, {"value": "C", "label": "C  The bakeries would not otherwise sell it"}, {"value": "D", "label": "D  Daniyar bakes it himself"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Every Thursday evening, Daniyar collects leftover bread from three bakeries and drives it to a shelter for homeless people. He started two years ago, after his mother, a nurse at the shelter, mentioned that breakfasts often ran out. At first he went by bus and could carry only two bags. Last spring he bought a small second-hand van, although it meant giving up his gym membership. The shelter’s manager says that since Daniyar began, no one has had to leave without breakfast on Fridays. When a newspaper asked to interview him, he agreed only if the article named the bakeries rather than him.", "teacher_notes": "1 C — his mother mentioned it.\n2 A — a trade-off implies limited money.\n3 B — by bus he could carry only two bags.\n4 D — “no one has had to leave without breakfast” since he began.\n5 A — named the bakeries rather than him.\n6 C — “leftover” bread.\nDifferent text from R18; not a calibrated equivalent form.", "focus": "Infer unstated meaning: reach conclusions the text supports but does not state."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'2daf0ca38f1bbfd365431171db16192c00ba857168be108230c2552118760aa0',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r20-v1','0.1.0','City trees: main point or detail?','reading','guided_practice','Read the passage. For each paragraph, choose the letter, A, B, C or D, that gives its MAIN point. The other options are details or ideas from elsewhere.','Find the sentence the rest of the paragraph explains or supports. Examples, numbers and reasons are usually supporting details.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph 1", "accepted_answers": ["A"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  Trees make city streets cooler"}, {"value": "B", "label": "B  One tree can lower the temperature by several degrees"}, {"value": "C", "label": "C  Pavements stay cool after sunset"}, {"value": "D", "label": "D  Trees grow fastest in summer"}]}, {"id": "q2", "prompt": "Paragraph 2", "accepted_answers": ["B"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  Hospital patients recover faster with a view of trees"}, {"value": "B", "label": "B  Trees are good for people’s health"}, {"value": "C", "label": "C  People on tree-lined streets feel less stress"}, {"value": "D", "label": "D  Trees make streets cooler"}]}, {"id": "q3", "prompt": "Paragraph 3", "accepted_answers": ["C"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  Roots can damage pipes"}, {"value": "B", "label": "B  Dead branches must be removed"}, {"value": "C", "label": "C  Looking after city trees is expensive"}, {"value": "D", "label": "D  Some species drop few branches"}]}, {"id": "q4", "prompt": "Paragraph 4", "accepted_answers": ["D"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  Some trees have deep roots"}, {"value": "B", "label": "B  Some trees drop few branches"}, {"value": "C", "label": "C  Roots damage pavements"}, {"value": "D", "label": "D  Choosing suitable species lowers the costs"}]}, {"id": "q5", "prompt": "Paragraph 5", "accepted_answers": ["A"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  Residents are being asked to help care for trees"}, {"value": "B", "label": "B  People can water trees in dry weeks"}, {"value": "C", "label": "C  People can adopt a tree"}, {"value": "D", "label": "D  Trees reduce stress"}]}, {"id": "q6", "prompt": "Paragraph 6", "accepted_answers": ["B"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  More trees will solve every city problem"}, {"value": "B", "label": "B  The benefits of trees outweigh their costs"}, {"value": "C", "label": "C  Trees are expensive"}, {"value": "D", "label": "D  Residents should water trees"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 12, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "1. Trees make city streets cooler in summer. A single large tree can lower the temperature beneath it by several degrees, and shaded pavements stay cooler long after sunset.\n\n2. Trees also improve people’s health. Patients in hospital rooms with a view of trees have been found to recover faster, and people living on tree-lined streets report less stress.\n\n3. However, city trees are expensive to look after. Their roots can damage pipes and pavements, and dead branches must be removed before they fall.\n\n4. Choosing the right species reduces these costs. Some trees have deep roots that stay away from pipes, and others drop few branches.\n\n5. Many cities now ask residents to help. In some places, people can adopt a tree and water it during dry weeks.\n\n6. Planting more trees will not solve every city problem, but their benefits are greater than their costs.", "teacher_notes": "Main points are the first sentence of each paragraph here; the other options are supporting details (B, C in 1; A, C in 2 …) or come from other paragraphs.\n6: A misreads “will not solve every city problem”.\nTeach: ask “what does the rest of the paragraph prove?”", "focus": "Distinguish main and supporting ideas: tell the point of a paragraph from the examples and details that support it."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'eb91031573b2d3073ed7c214b4d4d510087035814b6a2aacf46b1f6fe30a4fc4',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r21-v1','0.1.0','Working from home: main point or detail?','reading','independent_check','Read the passage. For each paragraph, choose the letter, A, B, C or D, that gives its MAIN point. The other options are details or ideas from elsewhere. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Find the sentence the rest of the paragraph explains or supports. Examples, numbers and reasons are usually supporting details.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Paragraph 1", "accepted_answers": ["C"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  More than half of staff in some companies work at home two days a week"}, {"value": "B", "label": "B  Staff work at home on Fridays"}, {"value": "C", "label": "C  Working from home has become common"}, {"value": "D", "label": "D  Offices are closing"}]}, {"id": "q2", "prompt": "Paragraph 2", "accepted_answers": ["A"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  Many employees feel more productive at home"}, {"value": "B", "label": "B  Employees start work earlier"}, {"value": "C", "label": "C  Employees are interrupted less"}, {"value": "D", "label": "D  Managers worry about teamwork"}]}, {"id": "q3", "prompt": "Paragraph 3", "accepted_answers": ["B"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  New employees rarely meet colleagues"}, {"value": "B", "label": "B  Managers are concerned about teamwork"}, {"value": "C", "label": "C  New staff learn from experienced colleagues"}, {"value": "D", "label": "D  Teams have office days"}]}, {"id": "q4", "prompt": "Paragraph 4", "accepted_answers": ["D"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  Teams have meetings in the office"}, {"value": "B", "label": "B  Training happens on office days"}, {"value": "C", "label": "C  Everyone works at home"}, {"value": "D", "label": "D  Agreed office days are a compromise"}]}, {"id": "q5", "prompt": "Paragraph 5", "accepted_answers": ["A"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  Office design is changing"}, {"value": "B", "label": "B  Desks are being removed"}, {"value": "C", "label": "C  Quiet areas are being added"}, {"value": "D", "label": "D  Employees prefer meeting rooms"}]}, {"id": "q6", "prompt": "Paragraph 6", "accepted_answers": ["C"], "taxonomy_node_id": "2b18f4c1-ed3c-4281-b352-8057fa69494b", "supporting_node_id": "492b5389-b4b7-4efc-b08f-e62d17ce46ff", "options": [{"value": "A", "label": "A  Experts know the long-term effects"}, {"value": "B", "label": "B  Offices will return to the old pattern"}, {"value": "C", "label": "C  The change is likely to last, although its effects are not yet known"}, {"value": "D", "label": "D  Working from home is unpopular"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "1. In some companies, more than half of the staff now spend at least two days a week at home. Working from home has clearly become common in many offices.\n\n2. Without a daily journey, employees start earlier, and they are interrupted less. Many say they are more productive at home.\n\n3. Managers, however, worry about teamwork. New employees in particular may find it hard to learn from experienced colleagues they rarely meet.\n\n4. Some firms have found a compromise. Teams agree on two “office days” each week when everyone comes in for meetings and training.\n\n5. Offices themselves are changing as a result. Rows of desks are being replaced by meeting rooms and quiet areas.\n\n6. It is too early to know the long-term effects, but few experts expect offices to return to the old pattern.", "teacher_notes": "Note: in 1 and 2 the main point comes AFTER the supporting detail — students who always pick the first sentence will choose A in paragraph 1 and B in 2.\n6: B reverses “few experts expect … return”.\nDifferent text from R20; not a calibrated equivalent form.", "focus": "Distinguish main and supporting ideas: tell the point of a paragraph from the examples and details that support it."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'088f049a14d1b39abd033a2b6245e4f7a74774418039e1845d9ae9ca9dd1471a',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r22-v1','0.1.0','Tourism in small towns: the writer’s views','reading','guided_practice','Read the passage. Do the statements agree with the views of the writer? Choose YES if the statement agrees with the writer’s views, NO if it contradicts them, or NOT GIVEN if it is impossible to say what the writer thinks.','Look for the writer’s own opinion words (in my view, I believe, I am not convinced). Do not confuse the writer’s view with what “some argue”.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Tourism is a simple way for small towns to become richer.", "accepted_answers": ["NO"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q2", "prompt": "Visitors should be discouraged from coming to small towns.", "accepted_answers": ["NO"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q3", "prompt": "Many tourism jobs are poorly paid.", "accepted_answers": ["YES"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q4", "prompt": "Limiting the number of holiday rentals is an effective solution.", "accepted_answers": ["NO"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q5", "prompt": "Holiday rentals should be taxed.", "accepted_answers": ["YES"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q6", "prompt": "Tourists would be willing to pay higher prices.", "accepted_answers": ["NOT GIVEN"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 12, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Tourism is often presented as an easy way for small towns to grow richer. In my view, this picture is too simple. It is true that visitors bring money to cafés and hotels, and I would not want to discourage them. But the jobs created are frequently seasonal and poorly paid, and house prices tend to rise as owners turn homes into holiday rentals. Some argue that local councils should simply limit the number of rentals. I am not convinced this works; in the towns I have studied, owners found ways around such rules. A better approach, I believe, is to tax holiday rentals and use the money to build homes for local workers. Whether tourists themselves would accept higher prices is a question I cannot answer.", "teacher_notes": "1 NO — “this picture is too simple”.\n2 NO — “I would not want to discourage them”.\n3 YES — “frequently seasonal and poorly paid”.\n4 NO — “I am not convinced this works” (the limit is what “some argue”).\n5 YES — “A better approach, I believe, is to tax holiday rentals”.\n6 NOT GIVEN — “a question I cannot answer”.\nTeach: YES/NO is about the writer’s opinion, not facts in the world.", "focus": "Identify viewpoint and attitude: separate the writer’s opinion from other people’s views and from facts."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'ba092358a214a6585fd0568f80d623dad22afb7efb19b4daafa5ef28408d9730',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r23-v1','0.1.0','Electric scooters: the writer’s views','reading','independent_check','Read the passage. Do the statements agree with the views of the writer? Choose YES if the statement agrees with the writer’s views, NO if it contradicts them, or NOT GIVEN if it is impossible to say what the writer thinks. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Look for the writer’s own opinion words (in my view, I believe, I am not convinced). Do not confuse the writer’s view with what “some argue”.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Electric scooters are, overall, a good thing for cities.", "accepted_answers": ["YES"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q2", "prompt": "Scooters cost more to use than taxis.", "accepted_answers": ["NO"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q3", "prompt": "Scooters left on pavements are a genuine danger.", "accepted_answers": ["YES"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q4", "prompt": "Cities that banned scooters made the right decision.", "accepted_answers": ["NO"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q5", "prompt": "There is good evidence that scooters reduce air pollution.", "accepted_answers": ["NO"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}, {"id": "q6", "prompt": "Scooter companies should pay for the parking areas.", "accepted_answers": ["NOT GIVEN"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "bcddba69-28bc-436c-bb54-01a3c5733099", "options": [{"value": "YES", "label": "YES"}, {"value": "NO", "label": "NO"}, {"value": "NOT GIVEN", "label": "NOT GIVEN"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "Rental electric scooters have appeared in many cities, and opinions about them are divided. I think they are, on balance, a positive development. They allow people to make short journeys without a car, and they are cheaper than taxis. Critics say that scooters left on pavements are dangerous for pedestrians, and I agree that this is a real problem. However, banning scooters, as some cities have done, seems to me an overreaction. Requiring riders to leave scooters in marked parking areas would solve most of the difficulty. Some people also claim that scooters reduce air pollution, but I have seen no convincing evidence of this, since many riders would otherwise have walked.", "teacher_notes": "1 YES — “on balance, a positive development”.\n2 NO — “cheaper than taxis”.\n3 YES — “I agree that this is a real problem”.\n4 NO — “an overreaction”.\n5 NO — “I have seen no convincing evidence”.\n6 NOT GIVEN — who pays is not discussed.\nDifferent text from R22; not a calibrated equivalent form.", "focus": "Identify viewpoint and attitude: separate the writer’s opinion from other people’s views and from facts."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'444183285c5e26ae399f4332301936de88502976fe5db5edf6cada6f799240c1',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r24-v1','0.1.0','Desert farming: meaning from context','reading','guided_practice','Read the passage. Choose the meaning, A, B, C or D, of each word as it is used in the passage.','Use the sentence around the word: look for an explanation, an example, a contrast (yet, but) or a result nearby.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "“revived”", "accepted_answers": ["A"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  brought back into use"}, {"value": "B", "label": "B  invented for the first time"}, {"value": "C", "label": "C  sold to others"}, {"value": "D", "label": "D  stopped using"}]}, {"id": "q2", "prompt": "“arid”", "accepted_answers": ["B"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  very cold"}, {"value": "B", "label": "B  very dry"}, {"value": "C", "label": "C  crowded"}, {"value": "D", "label": "D  rich in plants"}]}, {"id": "q3", "prompt": "“laborious”", "accepted_answers": ["C"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  dangerous"}, {"value": "B", "label": "B  cheap"}, {"value": "C", "label": "C  needing a lot of hard work"}, {"value": "D", "label": "D  quick"}]}, {"id": "q4", "prompt": "“durable”", "accepted_answers": ["D"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  attractive"}, {"value": "B", "label": "B  modern"}, {"value": "C", "label": "C  easily broken"}, {"value": "D", "label": "D  long-lasting"}]}, {"id": "q5", "prompt": "“sceptical”", "accepted_answers": ["A"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  doubtful"}, {"value": "B", "label": "B  excited"}, {"value": "C", "label": "C  angry"}, {"value": "D", "label": "D  well informed"}]}, {"id": "q6", "prompt": "“dispelled”", "accepted_answers": ["B"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  increased"}, {"value": "B", "label": "B  removed"}, {"value": "C", "label": "C  written down"}, {"value": "D", "label": "D  shared"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "In parts of North Africa, farmers have revived an ancient method of growing vegetables in arid land, where rain may fall only a few times a year. They dig deep pits and line them with stones, which stay cool and gather moisture from the night air. The technique is laborious: a single pit can take a family several days to build. Yet once completed, it is remarkably durable, lasting for decades with little repair. Agricultural experts were at first sceptical, doubting that such a simple system could feed many people. Their doubts were dispelled when harvests in a trial village tripled in five years.", "teacher_notes": "1 A — “an ancient method” → brought back.\n2 B — “rain may fall only a few times a year”.\n3 C — explained after the colon: several days to build.\n4 D — “lasting for decades with little repair”.\n5 A — “doubting that …”.\n6 B — doubts disappear when harvests triple.\nTeach: underline the clue that proves each meaning.", "focus": "Infer word meaning from context: work out an unfamiliar word from the clues around it."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'463923de75e120637ce6c03adf22868bd1839a5f34f44346033166f742bc3562',true) on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r25-v1','0.1.0','Lighthouse keepers: meaning from context','reading','independent_check','Read the passage. Choose the meaning, A, B, C or D, of each word as it is used in the passage. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Use the sentence around the word: look for an explanation, an example, a contrast (yet, but) or a result nearby.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "“isolated”", "accepted_answers": ["C"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  very tall"}, {"value": "B", "label": "B  brightly lit"}, {"value": "C", "label": "C  far from other people"}, {"value": "D", "label": "D  newly built"}]}, {"id": "q2", "prompt": "“neglect”", "accepted_answers": ["A"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  fail to give attention to"}, {"value": "B", "label": "B  enjoy"}, {"value": "C", "label": "C  repair"}, {"value": "D", "label": "D  share with others"}]}, {"id": "q3", "prompt": "“postponed”", "accepted_answers": ["D"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  cancelled for ever"}, {"value": "B", "label": "B  increased"}, {"value": "C", "label": "C  paid for"}, {"value": "D", "label": "D  delayed"}]}, {"id": "q4", "prompt": "“self-sufficient”", "accepted_answers": ["B"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  lonely"}, {"value": "B", "label": "B  able to provide for themselves"}, {"value": "C", "label": "C  wealthy"}, {"value": "D", "label": "D  unwell"}]}, {"id": "q5", "prompt": "“automated”", "accepted_answers": ["A"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  operated by machines"}, {"value": "B", "label": "B  closed to visitors"}, {"value": "C", "label": "C  painted"}, {"value": "D", "label": "D  sold"}]}, {"id": "q6", "prompt": "“monotonous”", "accepted_answers": ["C"], "taxonomy_node_id": "aafe14e8-c993-48b3-ae4a-2c26b2021897", "supporting_node_id": "e3155f38-aea7-4267-a0c3-44273b1d7d14", "options": [{"value": "A", "label": "A  dangerous"}, {"value": "B", "label": "B  well paid"}, {"value": "C", "label": "C  dull and repetitive"}, {"value": "D", "label": "D  noisy"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "For centuries, lighthouse keepers lived in isolated towers, often many kilometres from the nearest village. Their main task was to keep the lamp lit throughout the night, a duty they could never neglect, since a single dark hour might cause a shipwreck. Supplies arrived by boat, but in rough weather deliveries could be postponed for weeks. Keepers therefore stored enough food to be self-sufficient. Today, almost all lighthouses are automated, and the remaining towers are maintained by engineers who visit only occasionally. Some former keepers say they miss the solitude, although others admit that the life was monotonous.", "teacher_notes": "1 C — “many kilometres from the nearest village”.\n2 A — “a single dark hour might cause a shipwreck”.\n3 D — “for weeks” in rough weather.\n4 B — “therefore stored enough food”.\n5 A — engineers only visit occasionally.\n6 C — contrast with “miss the solitude”.\nDifferent text from R24; not a calibrated equivalent form.", "focus": "Infer word meaning from context: work out an unfamiliar word from the clues around it."}'::jsonb,'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_04.json 0.1.0"}'::jsonb,'97ede741fbd1134b10533873b03db27abd63e389961994a66954687e5c932fd3',true) on conflict (code) do nothing;
